<script setup lang="ts">
import { onMounted,reactive,ref } from 'vue'
import { anularTramite, detalleTramite, listarTramites } from '../services/tramites'
import type { Options, Tramite } from '../interfaces/tramites.interface'
const rows=ref<Tramite[]>([]),options=ref<Options>({tipos:[],categorias:[],estados:[],distritos:[]}),total=ref(0),lastPage=ref(1),loading=ref(false),error=ref(''),success=ref(''),detail=ref<Tramite|null>(null)
const filters=reactive({criterio:'',tipo:'',categoria:'',estado:'',distrito_id:'',desde:'',hasta:'',page:1})
async function load(page=1){filters.page=page;loading.value=true;error.value='';try{const r=await listarTramites(filters);rows.value=r.data;total.value=r.total;lastPage.value=r.last_page;options.value=r.options}catch(e){error.value=message(e)}finally{loading.value=false}}
async function show(item:Tramite){try{detail.value=await detalleTramite(item.id)}catch(e){error.value=message(e)}}async function remove(item:Tramite){if(!confirm(`¿Anular el trámite ${item.numero||'#'+item.id}?`))return;try{await anularTramite(item.id);success.value='Trámite anulado correctamente.';detail.value=null;await load()}catch(e){error.value=message(e)}}function message(e:unknown){return e instanceof Error?e.message:'No se pudo completar la operación.'}onMounted(()=>load())
</script>
<template><div class="page"><nav><RouterLink to="/inicio">Inicio</RouterLink> / EVAN / Comercialización / Trámites</nav><header class="hero"><div class="mark">TR</div><div><small>EVAN · COMERCIALIZACIÓN</small><h1>Seguimiento de trámites</h1><p>Bandeja consolidada de solicitudes, reclamos y avance de procedimientos.</p></div><strong>{{total}} trámites</strong><RouterLink class="new" to="/modulos/comercial/comercializacion/solicitudes">+ Registrar solicitud</RouterLink></header><p v-if="success" class="flash">✓ {{success}}</p><p v-if="error" class="flash error">{{error}}</p><section class="filters"><label>Buscar<input v-model.trim="filters.criterio" placeholder="Número, cliente, DNI o concepto" @keyup.enter="load(1)"></label><label>Tipo<select v-model="filters.tipo"><option value="">Todos</option><option v-for="x in options.tipos" :key="x.id" :value="x.id">{{x.nombre}}</option></select></label><label>Estado<select v-model="filters.estado"><option value="">Todos</option><option v-for="x in options.estados" :key="x.id" :value="x.id">{{x.nombre}}</option></select></label><label>Distrito<select v-model="filters.distrito_id"><option value="">Todos</option><option v-for="x in options.distritos" :key="x.id" :value="x.id">{{x.nombre}}</option></select></label><label>Desde<input v-model="filters.desde" type="date"></label><label>Hasta<input v-model="filters.hasta" type="date"></label><button @click="load(1)">Consultar</button></section><div v-if="loading" class="empty">Cargando trámites…</div><div v-else-if="!rows.length" class="empty">No se encontraron trámites.</div>
<section v-else class="cards"><article v-for="item in rows" :key="item.id" :class="{done:item.finalizado}"><header><div><small>{{item.categoria}}</small><b>{{item.numero||'Documento #'+item.id}}</b></div><em>{{item.estado}}</em></header><h2>{{item.concepto}}</h2><p>{{item.cliente}} <small>{{item.documento}}</small></p><dl><div><dt>Registrado</dt><dd>{{item.fecha_registro}}</dd></div><div><dt>Distrito</dt><dd>{{item.distrito}}</dd></div><div><dt>Fase actual</dt><dd>{{item.fase_actual||'Sin iniciar'}}</dd></div></dl><div class="progress"><i :style="{width:(item.avance||0)+'%'}"></i></div><small class="percentage">{{item.avance||0}}% completado</small><footer><button @click="show(item)">Ver seguimiento</button><button v-if="item.puede_anular" class="danger" @click="remove(item)">Anular</button></footer></article></section><footer v-if="lastPage>1" class="pages"><button :disabled="filters.page<=1" @click="load(filters.page-1)">Anterior</button><span>{{filters.page}} / {{lastPage}}</span><button :disabled="filters.page>=lastPage" @click="load(filters.page+1)">Siguiente</button></footer>
<div v-if="detail" class="backdrop" @mousedown.self="detail=null"><section class="modal"><header><div><small>SEGUIMIENTO DEL TRÁMITE</small><h2>{{detail.numero||'Documento #'+detail.id}}</h2><p>{{detail.cliente}} · {{detail.documento}}</p></div><button @click="detail=null">×</button></header><div class="summary"><div><b>{{detail.categoria}}</b><span>Categoría</span></div><div><b>{{detail.estado}}</b><span>Estado</span></div><div><b>{{detail.fecha_registro}}</b><span>Registro</span></div><div><b>{{detail.avance||0}}%</b><span>Avance</span></div></div><section class="subject"><b>{{detail.concepto}}</b><span>{{detail.distrito}} · {{detail.direccion}}</span></section><h3>Flujo del procedimiento</h3><div class="timeline"><article v-for="phase in detail.fases" :key="phase.id" :class="phase.estado?.toLowerCase().replaceAll(' ','-')"><i>{{phase.secuencia}}</i><div><b>{{phase.accion}}</b><p>{{phase.descripcion}}</p><small>{{phase.seccion}} <template v-if="phase.tarea_id">· Tarea #{{phase.tarea_id}}</template></small></div><aside><strong>{{phase.estado||'PENDIENTE'}}</strong><small>{{phase.responsable}}</small><time>{{phase.fecha_atencion}}</time></aside></article></div><footer><button class="clear" @click="detail=null">Cerrar</button><button v-if="detail.puede_anular" class="danger-bg" @click="remove(detail)">Anular trámite</button></footer></section></div></div></template>
<style scoped>
