e{text-align:right}.modal footer{margin-top:14px;display:flex;justify-content:flex-end;gap:6px}.clear{color:#68757c!important;background:#edf1f3!important}.danger-bg{background:#a13f43!important}@media(max-width:1000px){.cards{grid-template-columns:1fr 1fr}.filters{align-items:stretch;flex-direction:column}.hero{flex-wrap:wrap}.hero strong{margin-left:0}}@media(max-width:560px){.cards,.summary{grid-template-columns:1fr}.timeline article{grid-template-columns:30px 1fr}.timeline aside{grid-column:2;text-align:left}}
</style>
